<script setup>
import { onMounted,reactive } from 'vue';import { ElMessage } from 'element-plus';import http from '../api/http';import { useAuthStore } from '../stores/auth';import { assetUrl } from '../utils/url'
const auth=useAuthStore(),form=reactive({nickname:'',avatarUrl:'',bio:''});onMounted(async()=>{await auth.refresh();Object.assign(form,{nickname:auth.user.nickname,avatarUrl:auth.user.avatarUrl||'',bio:auth.user.bio||''})});async function save(){try{await http.put('/api/users/me',form);await auth.refresh();ElMessage.success('个人资料已保存')}catch(e){ElMessage.error(e.message)}}
</script>
<template><div><div class="page-head"><div><h1>个人中心</h1><p>管理校园身份与个人介绍</p></div></div><div class="two-col"><section class="surface panel"><h3 class="panel-title">基本资料</h3><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="form.nickname"/></el-form-item><el-form-item label="头像 URL"><el-input v-model="form.avatarUrl" placeholder="可填写公开图片地址"/></el-form-item><el-form-item label="个人简介"><el-input v-model="form.bio" type="textarea" :rows="4" maxlength="255" show-word-limit/></el-form-item><el-button type="primary" @click="save">保存修改</el-button></el-form></section><aside class="section-stack"><section class="surface panel" style="text-align:center"><el-avatar :size="76" :src="assetUrl(form.avatarUrl)">{{auth.user?.nickname?.slice(0,1)}}</el-avatar><h2 style="margin-bottom:5px">{{auth.user?.nickname}}</h2><p class="muted">@{{auth.user?.username}} · {{auth.user?.role==='ADMIN'?'管理员':'学生用户'}}</p><div class="stat-grid" style="margin-top:20px"><div class="stat"><strong>{{auth.user?.availablePoints}}</strong><span>积分</span></div><div class="stat"><strong>{{auth.user?.frozenPoints}}</strong><span>冻结</span></div><div class="stat"><strong>{{auth.user?.creditScore}}</strong><span>信用</span></div></div></section><section class="surface panel"><p><strong>学号</strong><br/><span class="muted">{{auth.user?.studentNo||'未填写'}}</span></p><p><strong>校园邮箱</strong><br/><span class="muted">{{auth.user?.email||'未填写'}}</span></p><el-button class="full" @click="$router.push('/skills')">管理技能档案</el-button></section></aside></div></div></template>
